package com.primehr.rsp.selection.api;import com.primehr.rsp.selection.api.SelectionDtos.*;import com.primehr.rsp.selection.application.SelectionService;import com.primehr.security.AgencyScopeResolver;import jakarta.validation.Valid;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/primehr/applicant/v1/me/applications/{applicationId}/selection") @ConditionalOnProperty(name="primehr.applicant.enabled",havingValue="true") public class ApplicantSelectionController{private final SelectionService service;private final AgencyScopeResolver agency;public ApplicantSelectionController(SelectionService s,AgencyScopeResolver a){service=s;agency=a;}@GetMapping public ApplicantSelectionStatus status(Authentication a,@PathVariable String applicationId){return service.applicantStatus(agency.resolveAgencyId(a),a.getName(),applicationId);}@PostMapping("/response")public ApplicantSelectionStatus respond(Authentication a,@PathVariable String applicationId,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody ApplicantOfferResponse r){return service.applicantRespond(agency.resolveAgencyId(a),a.getName(),applicationId,r,c);}}
